const MODELS = {
  'openai/gpt-oss-120b': { fallback: 'openai/gpt-oss-20b' },
  'openai/gpt-oss-20b': { fallback: null },
};
const DAILY_TOKEN_BUDGET = 190000;
const DAILY_REQUEST_BUDGET = 950;
const TOKENS_PER_MINUTE_LIMIT = 8000;
const MAX_COMPLETION_TOKENS = 4000;
const CHARS_PER_TOKEN_ESTIMATE = 3;
const PURPOSE_PATTERN = /^[a-z][a-z0-9_]{2,39}$/;
const SCHEMA_NAME_PATTERN = /^[A-Za-z0-9_-]{1,64}$/;
const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const requests = $('Trigger · Called by A or B').all();
if (requests.length !== 1) {
  throw new Error(
    `LLM Gateway takes exactly one request per execution, got ${requests.length}. Call it with Execute Workflow mode "Run once for each item".`,
  );
}
const input = requests[0].json;
const ledger = $input.first().json;

function isBlank(value) {
  return value === null || value === undefined || value === '';
}

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function normalised(raw) {
  return {
    purpose: raw.purpose,
    model: raw.model,
    system: raw.system,
    user: raw.user,
    schema_name: raw.schema_name,
    json_schema: raw.json_schema,
    max_tokens: Number(raw.max_tokens),
    batch_id: isBlank(raw.batch_id) ? null : String(raw.batch_id),
    run_id: isBlank(raw.run_id) ? null : Number(raw.run_id),
  };
}

function problems(request) {
  const found = [];
  if (typeof request.purpose !== 'string' || !PURPOSE_PATTERN.test(request.purpose)) {
    found.push('purpose must be a lower-case name such as cohort_verdict');
  }
  if (!(request.model in MODELS)) {
    found.push(`model must be one of ${Object.keys(MODELS).join(', ')}`);
  }
  for (const field of ['system', 'user']) {
    if (typeof request[field] !== 'string' || request[field].trim() === '') {
      found.push(`${field} must be a non-empty string`);
    }
  }
  if (typeof request.schema_name !== 'string' || !SCHEMA_NAME_PATTERN.test(request.schema_name)) {
    found.push('schema_name must be 1-64 letters, digits, _ or -');
  }
  if (!isPlainObject(request.json_schema) || request.json_schema.type !== 'object') {
    found.push('json_schema must be a JSON schema whose root type is object');
  }
  if (!Number.isInteger(request.max_tokens) || request.max_tokens < 1 || request.max_tokens > MAX_COMPLETION_TOKENS) {
    found.push(`max_tokens must be a whole number from 1 to ${MAX_COMPLETION_TOKENS}`);
  }
  if (request.batch_id !== null && !UUID_PATTERN.test(request.batch_id)) {
    found.push('batch_id must be a UUID or empty');
  }
  if (request.run_id !== null && !(Number.isInteger(request.run_id) && request.run_id > 0)) {
    found.push('run_id must be a positive whole number or empty');
  }
  if (request.run_id !== null && request.batch_id === null) {
    found.push('run_id needs a batch_id');
  }
  return found;
}

function estimatedTokens(request) {
  const promptChars = request.system.length + request.user.length + JSON.stringify(request.json_schema).length;
  return Math.ceil(promptChars / CHARS_PER_TOKEN_ESTIMATE) + request.max_tokens;
}

function fitsBudget(usage, model, estimate) {
  const used = usage[model] || {};
  return Number(used.tokens ?? 0) + estimate <= DAILY_TOKEN_BUDGET && Number(used.calls ?? 0) < DAILY_REQUEST_BUDGET;
}

function state(request, fields) {
  return {
    request,
    requested_model: request.model,
    model: request.model,
    fallback_model: null,
    fallback_used: false,
    fallback_reason: null,
    estimated_tokens: null,
    attempt: 0,
    waits_on_model: 0,
    rate_limit_waits: 0,
    waited_seconds: 0,
    tokens: { prompt: 0, completion: 0 },
    next: 'call',
    wait_seconds: null,
    outcome: null,
    ...fields,
  };
}

function refused(request, kind, message, fields = {}) {
  return state(request, {
    ...fields,
    next: 'return',
    outcome: { ok: false, data: null, status: null, error_kind: kind, error: message, finish_reason: null, model: null, latency_ms: null },
  });
}

function planned(request) {
  const found = problems(request);
  if (found.length > 0) {
    return refused(request, 'bad_request', `LLM Gateway refused the request: ${found.join('; ')}`);
  }
  const estimate = estimatedTokens(request);
  if (estimate > TOKENS_PER_MINUTE_LIMIT) {
    return refused(
      request,
      'bad_request',
      `LLM Gateway refused the request: it needs an estimated ${estimate} tokens, more than Groq's ${TOKENS_PER_MINUTE_LIMIT} tokens per minute, so Groq could never serve it`,
      { estimated_tokens: estimate },
    );
  }
  if (!isPlainObject(ledger.usage)) {
    return refused(request, 'budget', 'LLM Gateway refused the request: the llm_calls ledger could not be read, so the daily budget cannot be checked', {
      estimated_tokens: estimate,
    });
  }
  const fallback = MODELS[request.model].fallback;
  const candidates = [request.model, fallback].filter((model) => model && fitsBudget(ledger.usage, model, estimate));
  if (candidates.length === 0) {
    return refused(
      request,
      'budget',
      `LLM Gateway refused the request: the daily budget (${DAILY_TOKEN_BUDGET} tokens, ${DAILY_REQUEST_BUDGET} calls per model in 24 h) has no room for an estimated ${estimate} tokens`,
      { estimated_tokens: estimate },
    );
  }
  const model = candidates[0];
  return state(request, {
    model,
    fallback_model: candidates.find((candidate) => candidate !== model && candidate === fallback) ?? null,
    fallback_used: model !== request.model,
    fallback_reason: model !== request.model ? 'budget' : null,
    estimated_tokens: estimate,
  });
}

return [{ json: planned(normalised(input)) }];

const call = $input.item.json;
const { request } = call;

return {
  json: {
    ...call,
    attempt: call.attempt + 1,
    groq_request: {
      model: call.model,
      temperature: 0,
      reasoning_effort: 'low',
      include_reasoning: false,
      max_completion_tokens: request.max_tokens,
      messages: [
        { role: 'system', content: request.system },
        { role: 'user', content: request.user },
      ],
      response_format: {
        type: 'json_schema',
        json_schema: { name: request.schema_name, strict: true, schema: request.json_schema },
      },
    },
  },
};

const MAX_WAITS_PER_MODEL = 3;
const MAX_WAIT_SECONDS = 60;
const DEFAULT_WAIT_SECONDS = 10;
const WAIT_MARGIN_SECONDS = 1;
const SWITCH_WAIT_SECONDS = 1;
const MAX_ERROR_CHARS = 300;
const MAX_SCHEMA_ERRORS = 5;

const { groq_request: sentRequest, ...call } = $('Attempt · Build Groq body').item.json;
const response = $input.item.json;
const status = typeof response.statusCode === 'number' ? response.statusCode : 0;
const body = response.body !== null && typeof response.body === 'object' ? response.body : {};
const usage = body.usage || {};
const promptTokens = Number.isInteger(usage.prompt_tokens) ? usage.prompt_tokens : null;
const completionTokens = Number.isInteger(usage.completion_tokens) ? usage.completion_tokens : null;
const latencyMs = typeof usage.total_time === 'number' ? Math.round(usage.total_time * 1000) : null;

function clip(text) {
  return String(text).slice(0, MAX_ERROR_CHARS);
}

function groqMessage() {
  const message = body.error && body.error.message;
  return message ? `: ${message}` : '';
}

function typeOf(value) {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array';
  if (typeof value === 'number') return Number.isInteger(value) ? 'integer' : 'number';
  return typeof value;
}

function typeMatches(value, expected) {
  const actual = typeOf(value);
  return actual === expected || (expected === 'number' && actual === 'integer');
}

function schemaErrors(value, schema, path, errors) {
  if (errors.length >= MAX_SCHEMA_ERRORS || schema === null || typeof schema !== 'object') return errors;
  if (schema.type !== undefined) {
    const types = [].concat(schema.type);
    if (!types.some((type) => typeMatches(value, type))) {
      errors.push(`${path} should be ${types.join(' or ')}, got ${typeOf(value)}`);
      return errors;
    }
  }
  if (Array.isArray(schema.enum) && !schema.enum.some((option) => option === value)) {
    errors.push(`${path} is not one of the allowed values`);
  }
  if (typeOf(value) === 'object' && schema.properties) {
    for (const key of schema.required || []) {
      if (!(key in value)) errors.push(`${path}.${key} is missing`);
    }
    if (schema.additionalProperties === false) {
      for (const key of Object.keys(value)) {
        if (!(key in schema.properties)) errors.push(`${path}.${key} is not allowed`);
      }
    }
    for (const [key, child] of Object.entries(schema.properties)) {
      if (key in value) schemaErrors(value[key], child, `${path}.${key}`, errors);
    }
  }
  if (typeOf(value) === 'array' && schema.items) {
    value.forEach((element, index) => schemaErrors(element, schema.items, `${path}[${index}]`, errors));
  }
  return errors.slice(0, MAX_SCHEMA_ERRORS);
}

function finish(outcome) {
  return { next: 'return', wait_seconds: null, outcome: { latency_ms: latencyMs, ...outcome } };
}

function failure(kind, message) {
  return finish({ ok: false, data: null, status, error_kind: kind, error: clip(message), finish_reason: null, model: call.model });
}

function retry(waitSeconds, changes) {
  return {
    next: 'retry',
    wait_seconds: waitSeconds,
    waited_seconds: call.waited_seconds + waitSeconds,
    outcome: null,
    ...changes,
  };
}

function switchToFallback(reason) {
  return retry(SWITCH_WAIT_SECONDS, {
    model: call.fallback_model,
    fallback_model: null,
    fallback_used: true,
    fallback_reason: reason,
    waits_on_model: 0,
  });
}

function retryAfterSeconds() {
  const raw = response.headers && response.headers['retry-after'];
  const seconds = Number(raw);
  return raw === undefined || raw === null || raw === '' || !Number.isFinite(seconds) ? null : seconds;
}

function onRateLimit() {
  const retryAfter = retryAfterSeconds();
  const wait = retryAfter === null ? DEFAULT_WAIT_SECONDS : Math.max(0, Math.ceil(retryAfter)) + WAIT_MARGIN_SECONDS;
  if (call.waits_on_model < MAX_WAITS_PER_MODEL && wait <= MAX_WAIT_SECONDS) {
    return retry(wait, { waits_on_model: call.waits_on_model + 1, rate_limit_waits: call.rate_limit_waits + 1 });
  }
  if (call.fallback_model) return switchToFallback('rate_limited');
  return failure(
    'rate_limited',
    `Groq rate limited (HTTP 429) on ${call.model} after ${call.rate_limit_waits} waits, retry-after ${retryAfter ?? 'not sent'} s${groqMessage()}`,
  );
}

function onServerError() {
  if (call.fallback_model) return switchToFallback('server_error');
  return failure('http_error', `Groq HTTP ${status}${groqMessage()}`);
}

function onNoResponse() {
  const error = response.error;
  const message = typeof error === 'string' ? error : (error && error.message) || 'unknown error';
  return failure('network', `No response from Groq: ${message}`);
}

function onSuccess() {
  const choice = Array.isArray(body.choices) ? body.choices[0] : undefined;
  if (!choice) return failure('invalid_reply', 'Groq answer rejected: the reply has no choices');
  if (choice.finish_reason !== 'stop') {
    return failure('invalid_reply', `Groq answer rejected: finish_reason=${choice.finish_reason}, so the JSON may be cut off`);
  }
  const content = choice.message && choice.message.content;
  if (typeof content !== 'string') return failure('invalid_reply', 'Groq answer rejected: the reply has no message content');
  let data;
  try {
    data = JSON.parse(content);
  } catch {
    return failure('invalid_reply', 'Groq answer rejected: the message content is not JSON');
  }
  const errors = schemaErrors(data, call.request.json_schema, '$', []);
  if (errors.length > 0) {
    return failure('invalid_reply', `Groq answer rejected: it does not match the schema: ${errors.join('; ')}`);
  }
  return finish({ ok: true, data, status, error_kind: null, error: null, finish_reason: 'stop', model: body.model || call.model });
}

function decide() {
  if (status === 200) return onSuccess();
  if (status === 429) return onRateLimit();
  if (status >= 500) return onServerError();
  if (status === 0) return onNoResponse();
  return failure('http_error', `Groq HTTP ${status}${groqMessage()}`);
}

return {
  json: {
    ...call,
    tokens: {
      prompt: call.tokens.prompt + (promptTokens ?? 0),
      completion: call.tokens.completion + (completionTokens ?? 0),
    },
    log: {
      purpose: call.request.purpose,
      model: call.model,
      prompt_tokens: promptTokens,
      completion_tokens: completionTokens,
      status,
      latency_ms: latencyMs,
      batch_id: call.request.batch_id,
      run_id: call.request.run_id,
    },
    ...decide(),
  },
};
